const crypto = require('crypto');

const item = $input.first();
const request = (item && item.json) || {};
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};

function getHeader(name) {
  const target = String(name).toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (String(key).toLowerCase() === target) {
      if (Array.isArray(value)) return typeof value[0] === 'string' ? value[0].trim() : '';
      return typeof value === 'string' ? value.trim() : '';
    }
  }
  return '';
}

function reject(code, message, statusCode = 401) {
  return [{ json: { authenticated: false, statusCode, code, error: message } }];
}

function safeEqualUtf8(a, b) {
  const bufA = Buffer.from(String(a || ''), 'utf8');
  const bufB = Buffer.from(String(b || ''), 'utf8');
  return bufA.length > 0 && bufA.length === bufB.length && crypto.timingSafeEqual(bufA, bufB);
}

let rawBody = '';
const binaryEntry = item && item.binary && item.binary.data;
const hasInlineBinary = Boolean(binaryEntry && typeof binaryEntry.data === 'string' && binaryEntry.data.length > 0 && !binaryEntry.id);
if (typeof request.rawBody === 'string') rawBody = request.rawBody;
else if (Buffer.isBuffer(request.rawBody)) rawBody = request.rawBody.toString('utf8');
else if (hasInlineBinary) rawBody = Buffer.from(binaryEntry.data, 'base64').toString('utf8');
else if (typeof request.body === 'string') rawBody = request.body;
else if (request.body !== undefined) rawBody = JSON.stringify(request.body);

let authScheme = null;
const webhookId = getHeader('webhook-id');
const webhookTs = getHeader('webhook-timestamp');
const webhookSig = getHeader('webhook-signature');
const slackSig = getHeader('x-slack-signature');
const slackTs = getHeader('x-slack-request-timestamp');
const githubSig = getHeader('x-hub-signature-256');
const telegramSecretHdr = getHeader('x-telegram-bot-api-secret-token');
const latticeSig = getHeader('x-lattice-signature-256');

if (webhookId && webhookTs && webhookSig) {
  const rawSecret = String(($env && $env.DX_WEBHOOK_SECRET) || '').trim();
  if (!rawSecret) return reject('CALLBACK_SECRET_NOT_CONFIGURED', 'DX_WEBHOOK_SECRET is not configured.');
  if (!/^\d{1,12}$/.test(webhookTs)) return reject('CALLBACK_TIMESTAMP_INVALID', 'Invalid webhook-timestamp.');
  const tsSec = Number(webhookTs);
  if (Math.abs(Math.floor(Date.now() / 1000) - tsSec) > 300) {
    return reject('CALLBACK_TIMESTAMP_EXPIRED', 'Webhook timestamp expired.');
  }
  const keyBytes = rawSecret.startsWith('whsec_') ? Buffer.from(rawSecret.slice(6), 'base64') : Buffer.from(rawSecret, 'utf8');
  const expected = crypto.createHmac('sha256', keyBytes).update(`${webhookId}.${webhookTs}.${rawBody}`, 'utf8').digest('base64');
  const ok = webhookSig.split(/\s+/).some((tok) => tok.startsWith('v1,') && safeEqualUtf8(tok.slice(3), expected));
  if (!ok) return reject('CALLBACK_SIGNATURE_INVALID', 'Standard Webhooks HMAC verification failed.');
  authScheme = 'standard_webhooks';
} else if (slackSig && slackTs) {
  const slackSecret = String(($env && $env.DX_SLACK_SIGNING_SECRET) || '').trim();
  if (!slackSecret) return reject('CALLBACK_SECRET_NOT_CONFIGURED', 'DX_SLACK_SIGNING_SECRET is not configured.');
  if (!/^\d{1,12}$/.test(slackTs)) return reject('CALLBACK_TIMESTAMP_INVALID', 'Invalid x-slack-request-timestamp.');
  if (Math.abs(Math.floor(Date.now() / 1000) - Number(slackTs)) > 300) {
    return reject('CALLBACK_TIMESTAMP_EXPIRED', 'Slack timestamp expired.');
  }
  const expected = 'v0=' + crypto.createHmac('sha256', slackSecret).update(`v0:${slackTs}:${rawBody}`, 'utf8').digest('hex');
  if (!safeEqualUtf8(slackSig, expected)) return reject('CALLBACK_SIGNATURE_INVALID', 'Slack signature verification failed.');
  authScheme = 'slack_v0';
} else if (githubSig) {
  const ghSecret = String(($env && $env.DX_GITHUB_WEBHOOK_SECRET) || '').trim();
  if (!ghSecret) return reject('CALLBACK_SECRET_NOT_CONFIGURED', 'DX_GITHUB_WEBHOOK_SECRET is not configured.');
  const expected = 'sha256=' + crypto.createHmac('sha256', ghSecret).update(rawBody, 'utf8').digest('hex');
  if (!safeEqualUtf8(githubSig, expected)) return reject('CALLBACK_SIGNATURE_INVALID', 'GitHub signature verification failed.');
  authScheme = 'github_sha256';
} else if (telegramSecretHdr) {
  const tgSecret = String(($env && $env.DX_TELEGRAM_WEBHOOK_SECRET) || '').trim();
  if (!tgSecret) return reject('CALLBACK_SECRET_NOT_CONFIGURED', 'DX_TELEGRAM_WEBHOOK_SECRET is not configured.');
  if (!safeEqualUtf8(telegramSecretHdr, tgSecret)) return reject('CALLBACK_SIGNATURE_INVALID', 'Telegram secret token mismatch.');
  authScheme = 'telegram_secret_token';
} else if (latticeSig) {
  const rawSecret = String(($env && $env.DX_WEBHOOK_SECRET) || '').trim();
  if (!rawSecret) return reject('CALLBACK_SECRET_NOT_CONFIGURED', 'DX_WEBHOOK_SECRET is not configured.');
  const expected = 'sha256=' + crypto.createHmac('sha256', rawSecret).update(rawBody, 'utf8').digest('hex');
  if (!safeEqualUtf8(latticeSig, expected)) return reject('CALLBACK_SIGNATURE_INVALID', 'Lattice SHA-256 signature verification failed.');
  authScheme = 'lattice_sha256';
} else {
  return reject('CALLBACK_HEADERS_MISSING', 'Missing inbound callback authentication signature headers.');
}

let parsedBody = request.body;
if (typeof parsedBody === 'string') {
  try { parsedBody = JSON.parse(parsedBody); } catch { return reject('CALLBACK_BODY_INVALID', 'Callback body must be valid JSON.', 400); }
} else if (parsedBody === undefined && rawBody) {
  try { parsedBody = JSON.parse(rawBody); } catch { return reject('CALLBACK_BODY_INVALID', 'Callback body must be valid JSON.', 400); }
}
if (!parsedBody || typeof parsedBody !== 'object' || Array.isArray(parsedBody)) {
  return reject('CALLBACK_BODY_INVALID', 'Callback body must be a JSON object.', 400);
}

return [{
  json: {
    authenticated: true,
    authScheme,
    body: parsedBody,
  },
}];

const inp = $input.first().json || {};
const authScheme = String(inp.authScheme || 'unknown');
let payload = inp.body && typeof inp.body === 'object' ? inp.body : {};

// Handle Slack interactive payload wrapper
if (typeof payload.payload === 'string') {
  try { payload = JSON.parse(payload.payload); } catch {}
}

const ALLOWLISTED_COLLECTIONS = new Set([
  'latticeCustomPartnerClaims',
  'latticeIncidentCases',
  'latticeOrders',
  'latticeRequests',
  'latticeServiceTickets',
]);

const DECISION_MAP = {
  approved: { status: 'approved', settlementStatus: 'approved' },
  approve: { status: 'approved', settlementStatus: 'approved' },
  approve_claim: { status: 'approved', settlementStatus: 'approved' },
  settled: { status: 'settled', settlementStatus: 'settled' },
  settle: { status: 'settled', settlementStatus: 'settled' },
  settle_claim: { status: 'settled', settlementStatus: 'settled' },
  acknowledged: { status: 'acknowledged', settlementStatus: 'in_review' },
  ack: { status: 'acknowledged', settlementStatus: 'in_review' },
  ack_incident: { status: 'acknowledged', settlementStatus: 'in_review' },
  rejected: { status: 'rejected', settlementStatus: 'rejected' },
  reject: { status: 'rejected', settlementStatus: 'rejected' },
  reject_claim: { status: 'rejected', settlementStatus: 'rejected' },
  disputed: { status: 'disputed', settlementStatus: 'disputed' },
  resolved: { status: 'resolved', settlementStatus: 'settled' },
};

let sourceApp = String(payload.sourceApp || '').trim().toLowerCase();
let organizationId = String(payload.organizationId || (payload.data && payload.data.organizationId) || '').trim();
let targetCollection = String(payload.targetCollection || (payload.data && payload.data.targetCollection) || '').trim();
let rawRecordId = payload.targetRecordId ?? (payload.data && payload.data.targetRecordId);
let rawDecision = String(payload.decision || payload.action || (payload.data && payload.data.decision) || '').trim().toLowerCase();
let actorRef = String(payload.actor || payload.partnerActor || '').trim();
let partnerReference = String(payload.partnerReference || payload.reference || '').trim() || null;
let note = String(payload.note || payload.resolutionNote || '').trim();

// Telegram callback_query format: "<decision>:<orgId>:<collection>:<recordId>"
if (payload.callback_query && typeof payload.callback_query === 'object') {
  sourceApp = sourceApp || 'telegram';
  const cq = payload.callback_query;
  actorRef = actorRef || String((cq.from && (cq.from.username || cq.from.id)) || 'telegram-user');
  const parts = String(cq.data || '').split(':');
  if (parts.length >= 4) {
    rawDecision = rawDecision || String(parts[0] || '').trim().toLowerCase();
    organizationId = organizationId || String(parts[1] || '').trim();
    targetCollection = targetCollection || String(parts[2] || '').trim();
    rawRecordId = rawRecordId ?? parts[3];
  }
}

// Slack interactive action value format: "<decision>:<orgId>:<collection>:<recordId>"
if (Array.isArray(payload.actions) && payload.actions.length > 0) {
  sourceApp = sourceApp || 'slack';
  const act = payload.actions[0] || {};
  actorRef = actorRef || String((payload.user && (payload.user.username || payload.user.id)) || 'slack-user');
  const parts = String(act.value || act.action_id || '').split(':');
  if (parts.length >= 4) {
    rawDecision = rawDecision || String(parts[0] || '').trim().toLowerCase();
    organizationId = organizationId || String(parts[1] || '').trim();
    targetCollection = targetCollection || String(parts[2] || '').trim();
    rawRecordId = rawRecordId ?? parts[3];
  }
}

// GitHub issue close event
if (payload.issue && typeof payload.issue === 'object') {
  sourceApp = sourceApp || 'github';
  actorRef = actorRef || String((payload.sender && payload.sender.login) || 'github-webhook');
  if (String(payload.action || '').toLowerCase() === 'closed') {
    rawDecision = rawDecision || 'resolved';
  }
  partnerReference = partnerReference || `GH-${payload.issue.number || ''}`;
}

if (!sourceApp) {
  sourceApp = authScheme === 'slack_v0' ? 'slack' : (authScheme === 'github_sha256' ? 'github' : (authScheme === 'telegram_secret_token' ? 'telegram' : 'partner_webhook'));
}

const targetRecordId = Number(rawRecordId);
const mapped = DECISION_MAP[rawDecision];
const validOrg = /^[a-zA-Z0-9_-]{1,80}$/.test(organizationId);

if (!validOrg || !ALLOWLISTED_COLLECTIONS.has(targetCollection) || !Number.isInteger(targetRecordId) || targetRecordId <= 0 || !mapped) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: 'CALLBACK_PAYLOAD_INVALID',
      message: 'organizationId, allowlisted targetCollection, positive targetRecordId, and valid decision are required.',
    },
  }];
}

const rawSettlement = Number(payload.settlementAmountVnd ?? (payload.data && payload.data.settlementAmountVnd));
const settlementAmountVnd = Number.isFinite(rawSettlement) && rawSettlement >= 0 ? rawSettlement : null;
const decidedAt = new Date().toISOString();

const updatePayload = {
  status: mapped.status,
  resolutionNote: (note || `2-way ${sourceApp} callback (${rawDecision}) by ${actorRef || sourceApp}`).slice(0, 500),
  ...(targetCollection === 'latticeCustomPartnerClaims' ? {
    settlementStatus: mapped.settlementStatus,
    externalAppSource: sourceApp,
    partnerDecisionAt: decidedAt,
    ...(partnerReference ? { partnerReference } : {}),
    ...(settlementAmountVnd !== null ? { settlementAmountVnd } : {}),
  } : {}),
  ...(targetCollection === 'latticeIncidentCases' && mapped.status === 'acknowledged' ? {
    acknowledgedAt: decidedAt,
    acknowledgedBy: (actorRef || sourceApp).slice(0, 120),
  } : {}),
  ...(targetCollection === 'latticeIncidentCases' && mapped.status === 'resolved' ? {
    clearedAt: decidedAt,
    clearedBy: (actorRef || sourceApp).slice(0, 120),
  } : {}),
};

return [{
  json: {
    valid: true,
    statusCode: 200,
    authScheme,
    sourceApp,
    organizationId,
    targetCollection,
    targetRecordId,
    decision: rawDecision,
    mappedStatus: mapped.status,
    settlementStatus: mapped.settlementStatus,
    partnerReference,
    settlementAmountVnd,
    actorRef: actorRef || sourceApp,
    decidedAt,
    updatePayload,
    eventPublishPayload: {
      organizationId,
      type: 'partner.settlement_callback',
      source: `n8n:external-app-callback:${sourceApp}`,
      subject: `${targetCollection}:${targetRecordId}`,
      data: {
        organizationId,
        sourceApp,
        authScheme,
        targetCollection,
        targetRecordId,
        decision: rawDecision,
        mappedStatus: mapped.status,
        settlementStatus: mapped.settlementStatus,
        partnerReference,
        settlementAmountVnd,
        actorRef: actorRef || sourceApp,
        decidedAt,
      },
    },
  },
}];

const norm = $('Normalize Inbound Action & Target').first().json || {};
const upd = $('Update Record Status in NocoBase').first().json || {};
const evt = $input.first().json || {};
const recordUpdated = !upd.error && [200, 201, 204].includes(Number(upd.statusCode || 200));
const eventPublished = !evt.error && [200, 201, 202].includes(Number(evt.statusCode || 200));
return [{
  json: {
    ok: recordUpdated,
    statusCode: recordUpdated ? 200 : 502,
    workflow: 'external-app-inbound-callback',
    authScheme: norm.authScheme,
    sourceApp: norm.sourceApp,
    organizationId: norm.organizationId,
    targetCollection: norm.targetCollection,
    targetRecordId: norm.targetRecordId,
    decision: norm.decision,
    mappedStatus: norm.mappedStatus,
    settlementStatus: norm.settlementStatus,
    recordUpdated,
    eventPublished,
    processedAt: new Date().toISOString(),
  },
}];
